insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g1_pe_v1'
from (values
('116.13.b.1.A',2,'A first grader slides sideways across the gym. Which foot pattern is this?','["step-together moving to the side", "rolling on the floor", "jumping on two feet in place", "walking backward only"]'::jsonb,0,'Sliding is a side step and close.','original'),
('116.13.b.1.A',3,'Which two skills have a quick "step-hop" rhythm, one foot after the other?','["sitting", "skipping", "crawling", "spinning"]'::jsonb,1,'Skipping is a step and a hop on each foot.','original'),
('116.13.b.1.A',2,'To keep your balance while running, your arms should...','["hold your ears", "stay in your pockets", "swing naturally by your sides", "stay frozen over your head"]'::jsonb,2,'Natural arm swing helps balance.','original'),
('116.13.b.1.B',2,'A quarter turn when jumping means you turn...','["all the way around twice", "upside down", "not at all", "one quarter of the way around"]'::jsonb,3,'A quarter turn is 90 degrees.','original'),
('116.13.b.1.B',2,'When you land from a jump, bend your...','["knees", "fingers", "elbows", "ears"]'::jsonb,0,'Bent knees absorb the landing.','original'),
('116.13.b.1.C',3,'Tracing a shape in the air with your finger while watching it uses...','["sleeping", "visual tracking", "pushing", "shouting"]'::jsonb,1,'Tracking follows what you are drawing.','original'),
('116.13.b.1.C',3,'A sequence of three skills could be...','["jump only", "hop only", "hop, jump, and spin", "spin only"]'::jsonb,2,'A sequence needs three skills in order.','original'),
('116.13.b.1.D',2,'Rolling at a low level means your body is...','["up in the air", "standing tall", "on a chair", "close to the floor"]'::jsonb,3,'Levels describe height.','original'),
('116.13.b.1.D',3,'Spinning faster makes you feel more...','["dizzy", "asleep", "cold", "calm"]'::jsonb,0,'Fast spinning affects balance.','original'),
('116.13.b.2.A',2,'How long should you hold your balance on one foot for this skill?','["one minute", "five seconds", "one second", "one hour"]'::jsonb,1,'The skill asks for about five seconds.','original'),
('116.13.b.2.A',3,'To balance on one foot, the free leg can be...','["tucked under the other", "dragging on the floor", "bent behind you", "in the air straight up only"]'::jsonb,2,'The free leg may be in many positions.','original'),
('116.13.b.2.B',2,'Swaying your body means you...','["hold very still", "run fast", "jump up and down", "move gently from side to side"]'::jsonb,3,'Swaying is a gentle movement.','original'),
('116.13.b.2.B',2,'Twisting your body means you...','["turn your middle without moving your feet", "jump high", "lie down", "clap"]'::jsonb,0,'Twisting rotates the torso.','original'),
('116.13.b.3.A',3,'Where should you aim when you throw underhand to a target?','["behind you", "at the center of the target", "at the floor far away", "at the ceiling"]'::jsonb,1,'Aim at the middle of the target.','original'),
('116.13.b.3.A',3,'For an underhand throw, your arm swings back and then...','["across your face", "up over your head", "forward toward the target", "into your pocket"]'::jsonb,2,'Swing back, then forward.','original'),
('116.13.b.3.B',3,'To catch a large ball softly, you should...','["turn your head away", "stiffen your arms", "swing at it", "reach out and pull the ball in toward your body"]'::jsonb,3,'Soft hands absorb the ball.','original'),
('116.13.b.3.B',2,'The best way to catch a ball that is tossed gently is to use...','["both hands", "only your foot", "only your head", "no hands"]'::jsonb,0,'Two hands help control a large ball.','original'),
('116.13.b.3.C',2,'Dribbling continuously means you...','["roll it", "keep bouncing the ball again and again", "throw it away", "bounce once and stop"]'::jsonb,1,'Continuous dribbling is repeated bounces.','original'),
('116.13.b.3.C',3,'Which hand should you use first for dribbling?','["neither hand", "your elbow", "your preferred hand", "both feet"]'::jsonb,2,'Start with the hand you prefer.','original'),
('116.13.b.3.D',3,'When dribbling with your foot while walking, you should keep the ball...','["behind a wall", "far ahead of you", "in your hands", "close to your feet"]'::jsonb,3,'Close control keeps the ball with you.','original'),
('116.13.b.3.E',2,'Before you kick a ball that is still, you should first...','["approach it with a step or two", "sit down", "run away from it", "close your eyes"]'::jsonb,0,'An approach adds power.','original'),
('116.13.b.3.F',3,'A partner volley means you...','["hide it", "hit a light object back and forth with a partner", "throw it far away", "sit on it"]'::jsonb,1,'Partners keep it in the air.','original'),
('116.13.b.3.G',3,'When you strike an object with a short paddle, you want it to go...','["backward only", "straight down", "upward", "into the floor"]'::jsonb,2,'The skill is to project it upward.','original'),
('116.13.b.3.H',2,'Jumping consecutively with a rope means you...','["walk away", "sit", "jump once and stop", "jump many times in a row"]'::jsonb,3,'Consecutive means one after another.','original'),
('116.13.b.3.I',2,'When turning a long rope, the turners should...','["swing it in a steady arc", "stand still with it", "tie it", "let it drop"]'::jsonb,0,'A steady turn helps the jumper.','original'),
('116.13.b.4.A',2,'Moving to a steady beat means your steps match the...','["wall", "rhythm", "weather", "floor"]'::jsonb,1,'Match your movement to the music.','original'),
('116.13.b.4.A',2,'To stay safe in general space, you should move...','["by pushing", "with your eyes closed", "without bumping into others", "by running into walls"]'::jsonb,2,'Safe movement avoids contact.','original'),
('116.13.b.4.B',3,'Traveling over an object means you...','["pass beneath it", "stop in front of it", "move away from it", "pass above it"]'::jsonb,3,'Over means above.','original'),
('116.13.b.4.B',3,'Traveling under a low bar means you...','["stay low and go beneath", "stand tall", "run around", "jump above"]'::jsonb,0,'Under means beneath.','original'),
('116.13.b.4.B',2,'Moving around a cone means you...','["pick it up", "circle past it", "sit on it", "go straight through it"]'::jsonb,1,'Around goes past the object.','original'),
('116.13.b.4.C',2,'Which describes a strong force when moving?','["a tiny tap", "a sleepy sigh", "a powerful push", "a whisper"]'::jsonb,2,'Strong force uses more power.','original'),
('116.13.b.4.C',2,'Which describes a light force?','["a hard shove", "a loud stomp", "a big jump", "a soft, gentle touch"]'::jsonb,3,'Light force is gentle.','original'),
('116.13.b.4.C',2,'Which pair shows opposite speeds?','["fast and slow", "red and blue", "loud and noisy", "big and large"]'::jsonb,0,'Fast and slow are opposites.','original'),
('116.13.b.5',2,'In a rhythmic activity, you can clap to the...','["color of the wall", "beat of the music", "name of a shoe", "height of a ball"]'::jsonb,1,'Rhythm follows the beat.','original'),
('116.13.b.5',3,'A repeating set of short and long sounds in music is called...','["a bike path", "a fitness test", "a rhythm pattern", "a gym rule"]'::jsonb,2,'Patterns repeat.','original'),
('116.13.b.6.A',3,'In a chasing game, you should avoid pushing and stay...','["completely still", "as close as possible", "on the walls", "a safe distance and keep your speed under control"]'::jsonb,3,'Good spacing keeps everyone safe.','original'),
('116.13.b.6.B',2,'To improve a skill, you can follow your teacher''s...','["instructions and tips", "snacks", "jokes", "bell"]'::jsonb,0,'Teacher tips help you get better.','original'),
('116.13.b.6.C',2,'Using equipment appropriately means you...','["throw it at others", "use it only the way your teacher says", "break it", "hide it"]'::jsonb,1,'Appropriate use is safe use.','original'),
('116.13.b.6.C',2,'Respecting personal space means...','["crowding others", "taking their ball", "keeping your hands and feet to yourself", "touching friends often"]'::jsonb,2,'Personal space belongs to each person.','original'),
('116.13.b.8.A',2,'When you jump rope for a while, your heart rate...','["disappears", "goes to zero", "stays asleep", "goes up"]'::jsonb,3,'Exercise raises heart rate.','original'),
('116.13.b.8.A',3,'You can feel your heart beat faster by placing your hand on your...','["chest", "elbow", "knee", "ear"]'::jsonb,0,'You can feel it on your chest.','original'),
('116.13.b.8.B',2,'A warm-up is done before exercise to...','["get you hurt", "get your body ready", "make you tired", "skip the game"]'::jsonb,1,'Warm-ups prepare muscles.','original'),
('116.13.b.8.B',2,'A cool-down after exercise helps your body...','["speed up", "stop breathing", "slow down and relax", "freeze"]'::jsonb,2,'Cool-downs slowly lower heart rate.','original'),
('116.13.b.8.C',2,'Which is an exercise that builds strong muscles?','["watching videos", "sitting", "napping", "push-ups or crab walks"]'::jsonb,3,'Strength exercises build muscle.','original'),
('116.13.b.9.A',2,'A health-related goal could be to...','["walk 10 minutes every day", "skip school", "eat only candy", "never sleep"]'::jsonb,0,'A healthy goal improves health.','original'),
('116.13.b.9.B',3,'You can measure improvement in jumping by...','["asking the wall", "counting how many jumps you make", "closing your eyes", "guessing"]'::jsonb,1,'Counting shows progress.','original'),
('116.13.b.9.B',3,'A measuring tool for how far you jump is a...','["spoon", "cup", "tape measure", "clock"]'::jsonb,2,'Tapes measure distance.','original'),
('116.13.b.10.A',2,'Which food gives you energy before exercise?','["a bag of chips only", "a lollipop only", "nothing", "a banana"]'::jsonb,3,'Fruit is a healthy energy source.','original'),
('116.13.b.10.A',3,'Which snack is a healthy source of energy?','["apple slices", "candy bars", "frosting", "soda"]'::jsonb,0,'Fruit supports activity.','original'),
('116.13.b.10.B',2,'Besides water, a healthy hydration option is...','["candy", "low-fat milk", "soda", "energy drinks"]'::jsonb,1,'Healthy drinks help hydration.','original'),
('116.13.b.11.A',3,'Which gear should you wear for roller skating?','["a swimsuit", "a scarf", "a helmet and pads", "sandals"]'::jsonb,2,'Safety equipment protects you.','original'),
('116.13.b.11.A',2,'What footwear is best for running games?','["flip flops", "socks only", "high heels", "closed-toe sneakers"]'::jsonb,3,'Sneakers support feet.','original'),
('116.13.b.11.B',2,'Water safety means you should swim...','["with a grown-up watching", "in storms", "without a lifeguard", "alone"]'::jsonb,0,'Never swim alone.','original'),
('116.13.b.11.B',2,'Sun safety means you should wear...','["nothing", "sunscreen and a hat", "a blindfold", "a winter coat"]'::jsonb,1,'Sun protection prevents burns.','original'),
('116.13.b.11.B',3,'Cycling safety means you should ride...','["with no hands", "in the dark without lights", "with a helmet and follow traffic rules", "in the middle of the road"]'::jsonb,2,'Helmets and rules keep riders safe.','original'),
('116.13.b.12.A',3,'A positive consequence of practicing is that you...','["lose the ball", "get worse", "forget it", "get better at the skill"]'::jsonb,3,'Practice improves skills.','original'),
('116.13.b.12.A',3,'A negative consequence of breaking a rule might be...','["losing a turn", "a prize", "more time to play", "a gold star"]'::jsonb,0,'Rules have consequences.','original'),
('116.13.b.12.B',2,'Everyone has different abilities. A kind response is to...','["tease them", "encourage others", "laugh at them", "ignore them"]'::jsonb,1,'Encouraging builds respect.','original'),
('116.13.b.12.C',2,'If you feel an impulse to grab, a good idea is to...','["yell", "grab quickly", "stop and think first", "run away"]'::jsonb,2,'Pausing helps control impulses.','original'),
('116.13.b.12.C',2,'Excited, nervous, and proud are all...','["sports", "shapes", "colors", "feelings"]'::jsonb,3,'Emotions are feelings.','original'),
('116.13.b.13.A',2,'On a team, cooperation means you...','["work together", "compete against your teammates", "work alone", "argue"]'::jsonb,0,'Teams cooperate.','original'),
('116.13.b.13.B',2,'If you disagree with a classmate, you can say...','["\"Go away.\"", "\"I see it differently.\"", "nothing and hit them", "\"You are wrong.\""]'::jsonb,1,'Respectful words resolve conflicts.','original'),
('116.13.b.14',3,'If you fall down during a game, perseverance means you...','["quit the game", "blame the floor", "get back up and keep trying", "hide"]'::jsonb,2,'Perseverance is trying again.','original'),
('116.13.b.14',2,'When you keep practicing a hard skill, you show...','["laziness", "anger", "boredom", "perseverance"]'::jsonb,3,'Sticking with it takes effort.','original'),
('116.13.b.15',3,'Accepting a coach''s tip means you...','["listen and try to use it", "walk away", "argue", "ignore it"]'::jsonb,0,'You learn by trying feedback.','original'),
('116.13.b.15',3,'Which is helpful feedback for a teammate?','["\"I quit.\"", "\"Try keeping your eyes on the ball.\"", "\"You are terrible.\"", "\"Don''t try.\""]'::jsonb,1,'Helpful feedback is specific and kind.','original'),
('116.13.b.16.A',2,'Moderate to vigorous activity makes you breathe...','["not at all", "slower", "harder", "sleepy"]'::jsonb,2,'Intense activity raises breathing.','original'),
('116.13.b.16.A',2,'About how much physical activity should kids get on most days?','["1 minute", "none", "5 seconds", "at least 60 minutes"]'::jsonb,3,'Kids need regular daily activity.','original'),
('116.13.b.16.B',2,'A way to be active for fun is to...','["play tag with friends", "watch TV", "sit in a chair", "stay in bed"]'::jsonb,0,'Active play can be fun.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
